    --k-primary-foreground: 85 80% 6%;
    --k-primary-hover: 85 100% 48%;
    --k-primary-soft: 85 50% 14%;
    --k-secondary: 190 100% 50%;
    --k-secondary-foreground: 190 70% 6%;
    --k-secondary-hover: 190 100% 44%;
    --k-muted: 270 30% 14%;
    --k-muted-foreground: 285 15% 60%;
    --k-accent: 25 100% 60%;
    --k-accent-foreground: 25 80% 10%;
    --k-destructive: 0 80% 55%;
    --k-destructive-foreground: 0 40% 96%;
    --k-destructive-hover: 0 80% 48%;
    --k-border: 270 30% 20%;
    --k-input: 270 30% 20%;
    --k-ring: 85 100% 60%;
    --k-info: 270 40% 16%;
    --k-info-foreground: 285 80% 75%;
  --k-radius: 1.5rem;
  }
}

/* Explicit dark */
[data-color-scheme=dark] {
  color-scheme: dark;
  --k-background: 270 45% 5%;
  --k-foreground: 285 35% 92%;
  --k-card: 270 40% 9%;
  --k-card-foreground: 285 35% 92%;
  --k-popover: 270 40% 10%;
  --k-popover-foreground: 285 35% 92%;
  --k-sidebar: 270 50% 3%;
  --k-primary: 85 100% 55%;
  --k-primary-foreground: 85 80% 6%;
  --k-primary-hover: 85 100% 48%;
  --k-primary-soft: 85 50% 14%;
  --k-secondary: 190 100% 50%;
  --k-secondary-foreground: 190 70% 6%;
  --k-secondary-hover: 190 100% 44%;
  --k-muted: 270 30% 14%;
  --k-muted-foreground: 285 15% 60%;
  --k-accent: 25 100% 60%;
  --k-accent-foreground: 25 80% 10%;
  --k-destructive: 0 80% 55%;
  --k-destructive-foreground: 0 40% 96%;
  --k-destructive-hover: 0 80% 48%;
  --k-border: 270 30% 20%;
  --k-input: 270 30% 20%;
  --k-ring: 85 100% 60%;
  --k-info: 270 40% 16%;
  --k-info-foreground: 285 80% 75%;
  --k-radius: 1.5rem;
}

/* Typography — bulbous early-3D display heads, crisp digital sans body. */
:root:root {
  font-family: Syne, ui-sans-serif, system-ui, sans-serif;
}
:where(h1) {
  font-family: Monoton, Syne, sans-serif;
  font-weight: 400;
  letter-spacing: 0.04em;
}
:where(h2, h3, h4) {
  font-family: Syne, ui-sans-serif, system-ui, sans-serif;
  font-weight: 700;
  letter-spacing: 0.02em;
}

/* surface: actions */
[k=button] {
  border-radius: calc(var(--k-radius) * 1.2);
  box-shadow: 0 4px 16px hsl(var(--k-primary) / 0.25);
  transition: box-shadow 200ms ease, background-color 200ms ease;
}
[k=button]:hover {
  box-shadow: 0 0 14px hsl(var(--k-primary) / 0.55), 0 0 32px hsl(var(--k-primary) / 0.25);
}
[k=item] {
  border-radius: var(--k-radius);
}
[k=chip], [k=chip-button] {
  border-radius: calc(var(--k-radius) * 2);
  border: 1px solid hsl(var(--k-border));
  background: hsl(var(--k-card));
}

/* surface: data display */
[k=card] {
  border: 1px solid hsl(var(--k-border));
  border-radius: var(--k-radius);
  box-shadow: 0 0 0 1px hsl(var(--k-secondary) / 0.1), 0 6px 24px hsl(var(--k-background) / 0.5);
}
[k=badge] {
  border-radius: calc(var(--k-radius) * 2);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  border: 1px solid hsl(var(--k-border));
}
[k=table] {
  border-color: hsl(var(--k-border));
}
[k=skeleton] {
  border-radius: var(--k-radius);
  background: linear-gradient(90deg, hsl(var(--k-muted)) 25%, hsl(var(--k-secondary) / 0.25) 50%, hsl(var(--k-muted)) 75%);
  background-size: 200% 100%;
  animation: k-delia-pulse 2.2s ease-in-out infinite;
}
@keyframes k-delia-pulse {
  to {
    background-position: -200% 0;
  }
}

/* surface: data input */
[k=input], [k=textarea], [k=select], [k=combobox-input], [k=listbox-input] {
  border: 1px solid hsl(var(--k-input));
  border-radius: var(--k-radius);
  background: hsl(var(--k-card));
}
[k=input]:focus, [k=textarea]:focus, [k=select]:focus {
  border-color: hsl(var(--k-ring));
  box-shadow: 0 0 12px hsl(var(--k-ring) / 0.4);
}
[k=field-description] {
  color: hsl(var(--k-muted-foreground));
  font-size: 0.875em;
}
[k=checkbox], [k=radio], [k=switch] {
  border-color: hsl(var(--k-input));
  border-radius: 0.375rem;
}

/* surface: feedback */
[k=alert] {
  border: 1px solid hsl(var(--k-border));
  border-radius: var(--k-radius);
  background: hsl(var(--k-card));
}
[k=alert][data-variant=destructive] {
  border-color: hsl(var(--k-destructive) / 0.5);
  box-shadow: 0 0 12px hsl(var(--k-destructive) / 0.3);
}
[k=tooltip] {
  background: hsl(var(--k-foreground));
  color: hsl(var(--k-background));
  border-radius: var(--k-radius);
  border: 1px solid hsl(var(--k-border));
}

/* surface: navigation */
[k=tablist] {
  border-color: hsl(var(--k-border));
}
[k=tab] {
  border-radius: calc(var(--k-radius) * 2);
}
[k=tab][aria-selected=true] {
  background: hsl(var(--k-primary-soft));
  box-shadow: inset 0 0 0 1px hsl(var(--k-primary) / 0.4);
}
[k=breadcrumb-link] {
  color: hsl(var(--k-muted-foreground));
}
[k=sidebar] {
  border-color: hsl(var(--k-border));
  background: hsl(var(--k-sidebar));
}

/* surface: layout */
[k=separator] {
  background: hsl(var(--k-border));
}
[k=popover] {
  border: 1px solid hsl(var(--k-border));
  border-radius: var(--k-radius);
  box-shadow: 0 8px 28px hsl(var(--k-background) / 0.6), 0 0 20px hsl(var(--k-secondary) / 0.15);
}
[k=scroll-area] {
  border-radius: var(--k-radius);
}

/* Focus ring — acid signal. */
[k]:focus-visible {
  outline: 2px solid hsl(var(--k-ring));
  outline-offset: 2px;
  box-shadow: 0 0 12px hsl(var(--k-ring) / 0.45);
}
